  let selectedIdx = [];
  let highlightOn = false;

  function renderSelection(){
    document.querySelectorAll('.cmp-card').forEach(card => {
      const idx = parseInt(card.getAttribute('data-idx'));
      const isSel = selectedIdx.includes(idx);
      card.classList.toggle('selected', isSel);
      const btn = card.querySelector('.cmp-add-btn');
      if(btn) btn.textContent = isSel ? '✓ Added' : '+ Add';
    });

    const count = selectedIdx.length;
    const countEl = document.getElementById('cmpCount');
    if(countEl){
      countEl.textContent = count + ' / 3 Selected';
      countEl.classList.toggle('full', count >= 3);
    }

    const bar = document.getElementById('cmpBar');
    const barText = document.getElementById('cmpBarText');
    if(bar) bar.classList.toggle('show', count >= 2);
    if(barText) barText.textContent = count + (count === 1 ? ' project selected' : ' projects selected');
  }

  function toggleSelect(idx){
    const pos = selectedIdx.indexOf(idx);
    if(pos > -1){
      selectedIdx.splice(pos, 1);
    } else {
      if(selectedIdx.length >= 3){
        alert("You can compare up to 3 projects at a time. Remove one to add another.");
        return;
      }
      selectedIdx.push(idx);
    }
    renderSelection();
  }

  function removeFromCompare(idx){
    const pos = selectedIdx.indexOf(idx);
    if(pos > -1) selectedIdx.splice(pos, 1);
    renderSelection();
    if(selectedIdx.length < 2){
      closeModal();
    } else {
      renderTable();
    }
  }

  function openModal(){
    if(selectedIdx.length < 2){
      alert("Please select at least 2 projects to compare.");
      return;
    }
    renderTable();
    document.getElementById('cmpModalOverlay').classList.add('open');
    document.body.style.overflow = 'hidden';
  }

  function closeModal(){
    document.getElementById('cmpModalOverlay').classList.remove('open');
    document.body.style.overflow = '';
  }

  function toggleHighlight(){
    highlightOn = !highlightOn;
    document.getElementById('highlightToggle').classList.toggle('on', highlightOn);
    renderTable();
  }

  function escapeHtml(str){
    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  function renderTable(){
    const rows = [
      {label:'Type', key:'type'},
      {label:'Tenure', key:'tenure'},
      {label:'Status', key:'status'},
      {label:'Completion', key:'completion'},
      {label:'Price', key:'price'},
      {label:'Size', key:'size'},
      {label:'Rooms', key:'rooms'},
      {label:'Location', key:'loc'}
    ];

    const table = document.getElementById('cmpTable');
    const title = document.getElementById('cmpModalTitle');
    title.textContent = 'Compare Projects (' + selectedIdx.length + ' / 3 Selected)';

    const waLink = document.getElementById('cmpWaLink');
    if(waLink && selectedIdx.length > 0){
      const names = selectedIdx.map(function(idx){ return PROJECTS[idx].name; });
      let namesText;
      if(names.length === 1){
        namesText = names[0];
      } else if(names.length === 2){
        namesText = names[0] + ' and ' + names[1];
      } else {
        namesText = names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
      }
      const msg = '(KNRE) Hi Keith, I\'m comparing ' + namesText + ' and would like your advice on which fits me best.';
      waLink.href = 'https://api.whatsapp.com/send/?phone=60102821568&text=' + encodeURIComponent(msg) + '&type=phone_number&app_absent=0';
    }

    let html = '<colgroup><col class="label-col">';
    selectedIdx.forEach(function(){ html += '<col>'; });
    html += '</colgroup><thead><tr><th></th>';

    selectedIdx.forEach(function(idx){
      const p = PROJECTS[idx];
      const grad = p.grad ? p.grad : '#1c1a17,#3a3226';
      const cardImg = document.querySelector('.cmp-card[data-idx="' + idx + '"] .cmp-card-photo');
      const photoSrc = cardImg ? cardImg.getAttribute('src') : '';
      const mediaContent = photoSrc
        ? '<img class="cmp-th-photo" src="' + photoSrc + '" alt="' + escapeHtml(p.name) + '">'
        : '<div class="cmp-th-icon">' + p.icon + '</div>';
      html += '<th><div class="cmp-th-media" style="background:linear-gradient(135deg,' + grad + ')">'
        + mediaContent
        + '<div class="cmp-th-remove" onclick="removeFromCompare(' + idx + ')">&times;</div>'
        + '</div>'
        + '<span class="cmp-th-name">' + escapeHtml(p.name) + '</span>'
        + '<span class="cmp-th-price">' + escapeHtml(p.price) + '</span>'
        + '</th>';
    });
    html += '</tr></thead><tbody>';

    rows.forEach(function(row){
      const values = selectedIdx.map(function(idx){ return PROJECTS[idx][row.key]; });
      const allSame = values.every(function(v){ return v === values[0]; });
      html += '<tr><td class="label">' + row.label + '</td>';
      values.forEach(function(v){
        const diffClass = (highlightOn && !allSame) ? ' diff' : '';
        html += '<td class="' + diffClass.trim() + '">' + escapeHtml(v) + '</td>';
      });
      html += '</tr>';
    });

    html += '</tbody>';
    table.innerHTML = html;
  }

  let cmpActiveTag = 'All';

  function applyFilters(){
    const searchInput = document.getElementById('cmpSearch');
    const searchVal = (searchInput ? searchInput.value : '').toLowerCase().trim();
    const areaVal = cmpActiveTag;
    let visibleCount = 0;

    document.querySelectorAll('.cmp-card').forEach(function(card){
      const idx = parseInt(card.getAttribute('data-idx'));
      const searchText = card.getAttribute('data-search') || '';
      const tag = PROJECTS[idx].tag;
      const matchesSearch = searchText.indexOf(searchVal) > -1;
      const matchesArea = areaVal === 'All' || tag === areaVal;
      const show = matchesSearch && matchesArea;
      card.style.display = show ? '' : 'none';
      if(show) visibleCount++;
    });

    const empty = document.getElementById('cmpEmpty');
    if(empty){
      empty.style.display = visibleCount === 0 ? 'block' : 'none';
    }
  }

  const cmpSearchEl = document.getElementById('cmpSearch');
  if(cmpSearchEl) cmpSearchEl.addEventListener('input', applyFilters);

  const cmpFiltersEl = document.getElementById('cmpFilters');
  if(cmpFiltersEl){
    cmpFiltersEl.addEventListener('click', function(e){
      const btn = e.target.closest('.cmp-filter-btn');
      if(!btn) return;
      document.querySelectorAll('.cmp-filter-btn').forEach(function(b){ b.classList.remove('active'); });
      btn.classList.add('active');
      cmpActiveTag = btn.getAttribute('data-tag');
      applyFilters();
    });
  }

  renderSelection();
